LoadOnClick:
import { useState } from 'react'
import { Button, Inline } from 'vellum-ui'

export function LoadOnClick() {
  const [loading, setLoading] = useState(false)
  return (
    <Inline>
      <Button
        variant="primary"
        loading={loading}
        onClick={() => {
          setLoading(true)
          setTimeout(() => setLoading(false), 1200)
        }}
      >
        Save changes
      </Button>
      <Button>Cancel</Button>
    </Inline>
  )
}
